{
  "case_id": "xsu_sg_002_permanence_requirement",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret siger direkte: \"Der er ikke et krav om, at tilstanden skal have været varig eller kendt som kronisk fra begyndelsen\". Det modsiger vejledningen, hvor udgangspunktet er, at man ikke er berettiget, hvis tilstanden ikke fra debut kan ses som varig eller kronisk. Svaret nævner heller ikke étårsudgangspunktet, og det tilføjer et krav om, at tilstanden \"forventes at bestå i længere tid eller på ubestemt tid\". Det afviger fra \"ikke væsentligt bedre inden for en længere årrække\"."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "To kritiske elementer mangler: omkring ét års varighed og symptomer eller følger i mindst et år før ansøgningen, samt muligheden for tidsbegrænset tillæg, når varighed er sandsynliggjort, men ikke endeligt fastslået. Udgangspunktet om, at tilstanden hverken af sig selv eller ved behandling bliver væsentligt bedre inden for en længere årrække, er kun delvist gengivet."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvornår en funktionsnedsættelse er varig, og hvad der gælder, hvis den ikke er varig eller kronisk fra begyndelsen. Indholdet er delvist forkert, men det er ikke irrelevant."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til SU's information om handicaptillæg (su.dk/handicaptillaeg). Det er en identificerbar kilde, men en generel henvisning og ikke til specifikke bestemmelser."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Den angivne kilde er en generel webside på su.dk og ikke en af de frosne autoritative kilder (SU-loven, SU-bekendtgørelsen eller vejledning nr. 10157). Den kan ikke verificeres inden for den frosne kildeafgrænsning."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "De frosne passager støtter ikke påstanden om, at der ikke er krav om varighed fra begyndelsen. Vejledningen siger det modsatte som udgangspunkt. Passagerne støtter heller ikke, at man kan søge igen efter midlertidighed eller sende nye oplysninger, og de støtter heller ikke formuleringen \"længere tid eller ubestemt tid\"."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer uunderstøttede regler: at der ikke er krav om varighed fra begyndelsen, at \"længere tid eller ubestemt tid\" er kriteriet, og at man kan søge igen eller sende nye oplysninger. Dertil kommer, at nyopstået tilstand kan opfylde kravet alene med lægelige oplysninger om forventet langvarighed."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke \"som udgangspunkt\" og \"omkring et år\" i forhold til tiden før ansøgning. Det mangler også den kvalificerede mulighed for tidsbegrænset tillæg ved sandsynliggjort men ikke endeligt fastslået varighed. Udgangspunktet om manglende ret ved ikke-varig debut er vendt om."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt rimeligt sammenhængende: varighed vurderes konkret, ingen krav om kronisk fra start, kronisk diagnose er ikke automatisk nok, og midlertidig tilstand opfylder normalt ikke kravet. Konklusionerne følger af de trin, svaret selv angiver, selv om præmissen er forkert i forhold til vejledningen."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør et udgangspunkt til en absolut negativ regel: \"Der er ikke et krav om...\". Vejledningen siger, at man som udgangspunkt ikke er berettiget, hvis tilstanden ikke fra debut er varig eller kronisk. Svaret får desuden \"kan søge igen\" til at fremstå som en regel uden støtte."
    }
  },
  "xhaile_coverage": {
    "A9": {
      "label": "partial",
      "reason": "Svaret behandler varighed som centralt krav, men beskriver det med forventning om længere tid eller ubestemt tid og ikke ud fra, at tilstanden ikke bliver væsentligt bedre inden for en længere årrække. Det nævner ikke eksplicit, at det er en grundlæggende forudsætning vedrørende art og grad."
    },
    "A12": {
      "label": "no",
      "reason": "Svaret nævner ikke ét års varighed eller mindst ét års symptomer før ansøgning. Det siger tværtimod, at der ikke er krav om varighed eller kronisk karakter fra begyndelsen, hvilket strider mod A12."
    }
  },
  "overall_notes": "Svaret har en citeret kilde, men indholdet er væsentligt forkert og ufuldstændigt. Det afviser kravet om varighed eller kronisk karakter fra debut, udelader étårsudgangspunktet og muligheden for tidsbegrænset tillæg ved sandsynliggjort varighed, og tilføjer uunderstøttede regler."
}

